import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"SLSA Build Attestation","description":"","frontmatter":{},"headers":[],"relativePath":"slsa.md","filePath":"slsa.md"}'),s={name:"slsa.md"};function r(l,e,n,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="slsa-build-attestation" tabindex="-1">SLSA Build Attestation <a class="header-anchor" href="#slsa-build-attestation" aria-label="Permalink to &quot;SLSA Build Attestation&quot;">​</a></h1><p>This repository publishes build provenance for release artifacts in accordance with <a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA (Supply-chain Levels for Software Artifacts)</a> Build specifications. SLSA provenance allows downstream consumers to verify that an artifact was built from the expected source repository, at the expected commit, by the expected build platform.</p><h2 id="target-level" tabindex="-1">Target Level <a class="header-anchor" href="#target-level" aria-label="Permalink to &quot;Target Level&quot;">​</a></h2><p><strong>Current target: SLSA Build L2 — partial coverage as of v0.14.11-canary.3</strong></p><p>The release pipeline is hosted on GitHub Actions, an isolated build platform that is owned and administered by GitHub. Provenance is generated automatically for every published release using <a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a> and the <code>attest-build-provenance</code> action. Provenance is signed by a GitHub- hosted OIDC token and stored in the <a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a> log alongside the artifact.</p><h3 id="what-is-enforced-today" tabindex="-1">What is enforced today <a class="header-anchor" href="#what-is-enforced-today" aria-label="Permalink to &quot;What is enforced today&quot;">​</a></h3><p>The <a href="../.github/workflows/release-evidence.yml">release-evidence gate</a> (workflow <code>.github/workflows/release-evidence.yml</code>) is triggered by:</p><ul><li><code>workflow_run</code> events from <code>Release</code> and <code>Release Attestation</code> workflows completing on <code>main</code>, or</li><li>manual <code>workflow_dispatch</code> with an optional commit SHA (defaults to the workflow&#39;s <code>HEAD</code>).</li></ul><p>The gate is <strong>post-merge</strong> by design: release evidence (SBOM, <code>BUILD_MANIFEST.txt</code>, SLSA provenance) is produced by <code>release.yml</code> and <code>release-attestation.yml</code>, which themselves only fire on push to <code>main</code>. Pre-merge validation cannot reach those artifacts. The gate validates:</p><ol><li>Version consistency between <code>VERSION</code>, <code>package.json</code>, and <code>Cargo.toml</code>.</li><li>A <code>Release</code> workflow run completed successfully on the same SHA, and a <code>Release Attestation</code> workflow run completed successfully on the same SHA.</li><li>Release + attestation artifacts downloaded into a single directory contain an SBOM (<code>SBOM.cdx.json</code> / <code>SBOM.spdx.json</code>), a <code>BUILD_MANIFEST.txt</code>, and an <code>.intoto.jsonl</code> provenance document.</li></ol><p><code>workflow_run</code> is used as the trigger so the gate cannot race against an in-flight <code>release.yml</code> run; by the time the gate starts, the upstream runs have a known <code>conclusion</code> value that the gate reads. Artifacts are downloaded from the matched runs using <code>actions/github-script@v7</code>&#39;s <code>listWorkflowRunArtifacts</code> and <code>downloadWorkflowRunArtifact</code> calls, so the validator scans the union of actual artifact files rather than container names.</p><h3 id="what-is-not-yet-enforced" tabindex="-1">What is not yet enforced <a class="header-anchor" href="#what-is-not-yet-enforced" aria-label="Permalink to &quot;What is not yet enforced&quot;">​</a></h3><p>SBOM generation and cosign signing of binaries are not yet wired into <code>release.yml</code>; today the gate verifies that the existing artifacts carry the expected file names. Closing that gap is tracked in <a href="./plans/tasks/release-evidence.html"><code>docs/plans/tasks/release-evidence.md</code></a>.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>The CI workflow lives at <a href="../.github/workflows/release-attestation.yml"><code>.github/workflows/release-attestation.yml</code></a> and is triggered:</p><ul><li>Automatically on every <code>release: published</code> event.</li><li>Manually via <code>workflow_dispatch</code> for ad-hoc provenance generation.</li></ul><p>The validation gate lives at <a href="../.github/workflows/release-evidence.yml"><code>.github/workflows/release-evidence.yml</code></a> and is triggered:</p><ul><li>Automatically via <code>workflow_run</code> whenever <code>Release</code> or <code>Release Attestation</code> completes on <code>main</code>.</li><li>Manually via <code>workflow_dispatch</code> with an optional commit SHA for ad-hoc re-validation of any commit.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artifac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KooshaPari</span></span></code></pre></div><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA Framework</a></li><li><a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a></li><li><a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a></li><li><a href="../.github/workflows/release-evidence.yml">Release evidence gate</a></li><li><a href="./plans/tasks/release-evidence.html">Release evidence plan</a></li></ul>',22)])])}const u=a(s,[["render",r]]);export{p as __pageData,u as default};
